fn slugify(title: Str) -> Str {
  let lower = str_lower(title);
  let slug = str_replace(lower, " ", "-");
  return slug;
}

fn is_empty_or_whitespace(s: Str) -> Bool {
  return str_trim(s).len() == 0;
}

fn main() -> Int {
  let slug = slugify("Hello World XIOM");
  return slug.len();
}
